"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowDownToLine, ArrowLeft, ArrowRight, Archive, Check, CheckCircle2, ChevronDown, ChevronUp, Circle, Clapperboard, Copy, ExternalLink, FileText, Film, FolderOpen, HelpCircle, Link2, Menu, Mic, Moon, MoreHorizontal, Plus, RefreshCw, Save, Search, Settings2, ShieldCheck, Sparkles, Sun, Trash2, Upload, Video, X } from "lucide-react";
import type { Asset, Job, Project, ProjectInput, Scene } from "@/lib/schema";
import { readiness } from "@/lib/schema";
import { Empty, Field, fileSize, fmtTime, MediaThumb, Spinner } from "./ui";
import VoiceControls from "./voice-controls";
import ErrorCenter from "./error-center";
import InlineErrors from "./inline-errors";
import {api,reportClientIssue} from "@/lib/client-api";

type Step="product"|"media"|"script"|"voice"|"capcut";
type Health={capcut:{cli:boolean;installed:boolean;message:string};ai:boolean;voice:boolean};
type JobSummary=Omit<Job,"snapshot">;
const steps=[{id:"product",label:"ข้อมูลสินค้า",icon:Link2},{id:"media",label:"ฟุตเทจจริง",icon:Film},{id:"script",label:"สคริปต์",icon:FileText},{id:"voice",label:"เสียงพากย์",icon:Mic},{id:"capcut",label:"CapCut",icon:Clapperboard}] as const;
const statusText:Record<Project["status"],string>={draft:"กำลังเตรียม",editing:"กำลังตัดต่อ",review:"รอตรวจงาน",done:"ตรวจงานแล้ว"};
const roleText:Record<string,string>={hook:"เปิดเรื่อง",demo:"สาธิตการใช้",detail:"รายละเอียด",cta:"ปิดท้าย",voiceover:"เสียงพากย์",music:"เพลง"};
const jobText:Record<Job["state"],string>={prepared:"พร้อมส่งต่อ",running:"กำลังทำงาน",completed:"มี draft แล้ว",failed:"ต้องตรวจสอบ",cancelled:"ยกเลิกแล้ว"};
function body(value:unknown){return JSON.stringify(value);}
function inputValues(p:Project):ProjectInput{
  const {id:_id,assets:_assets,revision:_revision,status:_status,archived:_archived,createdAt:_created,updatedAt:_updated,capcutUrl:_url,...values}=p;return values;
}

export default function Studio(){
  const [projects,setProjects]=useState<Project[]>([]),[project,setProject]=useState<Project|null>(null);
  const [step,setStep]=useState<Step>("script"),[health,setHealth]=useState<Health|null>(null);
  const [jobs,setJobs]=useState<JobSummary[]>([]),[events,setEvents]=useState<Array<{message:string;createdAt:string}>>([]);
  const [loading,setLoading]=useState(true),[busy,setBusy]=useState<string|null>(null),[dirty,setDirty]=useState(false);
  const [error,setError]=useState(""),[notice,setNotice]=useState(""),[query,setQuery]=useState(""),[showArchived,setShowArchived]=useState(false);
  const [selected,setSelected]=useState<string|null>(null),[previewId,setPreviewId]=useState<string|null>(null);
  const [help,setHelp]=useState(false),[mobileProjects,setMobileProjects]=useState(false),[light,setLight]=useState(false);
  const [linkInput,setLinkInput]=useState(""),[newName,setNewName]=useState(""),[newLink,setNewLink]=useState(""),[imported,setImported]=useState<{price:string;facts:string}|null>(null);
  const [manualUrl,setManualUrl]=useState(""),[manualDraft,setManualDraft]=useState(""),[jobPrompt,setJobPrompt]=useState("");
  const newDialog=useRef<HTMLDialogElement>(null),archiveDialog=useRef<HTMLDialogElement>(null),fileInput=useRef<HTMLInputElement>(null);
  const videoRef=useRef<HTMLVideoElement>(null),currentProject=useRef<Project|null>(null),dirtyRef=useRef(false);
  currentProject.current=project;dirtyRef.current=dirty;
  const acceptProject=useCallback((p:Project)=>{setProject(p);setProjects(prev=>[p,...prev.filter(x=>x.id!==p.id)]);setDirty(false);},[]);
  const loadList=useCallback(async()=>{const d=await api<{projects:Project[]}>("/api/projects?archived=1");setProjects(d.projects);return d.projects;},[]);
  const loadProject=useCallback(async(id:string)=>{
    const d=await api<{project:Project;jobs:JobSummary[];activity:Array<{message:string;createdAt:string}>}>(`/api/projects/${id}`);
    acceptProject(d.project);setJobs(d.jobs);setEvents(d.activity);setSelected(d.project.scenes[0]?.id||null);setPreviewId(null);localStorage.setItem("studio.project",id);
    if(d.project.scenes.length===0)setStep("product");else setStep("script");
  },[acceptProject]);
  useEffect(()=>{
    let active=true;
    Promise.allSettled([loadList(),api<Health>("/api/health")]).then(async results=>{
      if(!active)return;
      const first=results[0];if(first.status==="fulfilled"){
        const id=localStorage.getItem("studio.project");const target=first.value.find(p=>p.id===id&&!p.archived)||first.value.find(p=>!p.archived);
        if(target)await loadProject(target.id).catch(e=>setError(e.message));
      }else setError(first.reason.message);
      if(results[1].status==="fulfilled")setHealth(results[1].value);setLoading(false);
    });
    const theme=localStorage.getItem("studio.theme")==="light";setLight(theme);document.documentElement.dataset.theme=theme?"light":"dark";
    return()=>{active=false;};
  },[loadList,loadProject]);
  useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(""),7000);return()=>clearTimeout(timer);},[notice]);
  useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(dirtyRef.current){e.preventDefault();}};window.addEventListener("beforeunload",warn);return()=>window.removeEventListener("beforeunload",warn);},[]);
  const perform=async(label:string,fn:()=>Promise<void>)=>{setBusy(label);setError("");try{await fn();}catch(e){setError(e instanceof Error?e.message:"ทำรายการไม่สำเร็จ");if(!(e instanceof Error)||!e.message.includes(" — "))reportClientIssue({code:"ACTION_FAILED",source:label,message:e instanceof Error?e.message:"ทำรายการไม่สำเร็จ"});}finally{setBusy(null);}};
  const save=useCallback(async():Promise<Project|null>=>{
    const p=currentProject.current;if(!p)return null;
    const d=await api<{project:Project}>(`/api/projects/${p.id}`,{method:"PATCH",body:body({revision:p.revision,patch:inputValues(p)})});acceptProject(d.project);return d.project;
  },[acceptProject]);
  useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==="s"){e.preventDefault();if(currentProject.current&&dirtyRef.current&&!busy)void perform("save",async()=>{await save();setNotice("บันทึกโปรเจกต์แล้ว");});}};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key);});
  useEffect(()=>{
    if(!jobs.some(j=>j.state==="running")||!project)return;
    const timer=setInterval(async()=>{try{const d=await api<{project:Project;jobs:JobSummary[];activity:Array<{message:string;createdAt:string}>}>(`/api/projects/${project.id}`);setJobs(d.jobs);setEvents(d.activity);if(!dirtyRef.current)acceptProject(d.project);}catch{}},3000);
    return()=>clearInterval(timer);
  },[jobs,project?.id,acceptProject]);
  const edit=(patch:Partial<ProjectInput>)=>{setProject(p=>p?{...p,...patch}:p);setDirty(true);};
  const editScene=(id:string,patch:Partial<Scene>)=>{if(!project)return;edit({scenes:project.scenes.map(s=>s.id===id?{...s,...patch}:s),...(patch.narration!==undefined?{voiceAssetId:null}:{})});};
  const choose=async(id:string)=>{if(dirty&&!window.confirm("มีการแก้ไขที่ยังไม่บันทึก ต้องการออกจากโปรเจกต์นี้หรือไม่?"))return;await perform("load",async()=>{await loadProject(id);setHelp(false);setMobileProjects(false);});};
  const openNew=()=>{setNewName("");setNewLink("");setLinkInput("");setImported(null);newDialog.current?.showModal();};
  const upload=async(files:FileList|null)=>{if(!project||!files?.length)return;const id=project.id;await perform("upload",async()=>{
    if(dirty)await save();const form=new FormData();Array.from(files).forEach(f=>form.append("files",f));
    const d=await api<{project:Project;results:Array<{name:string;error?:string}>}>(`/api/projects/${id}/assets`,{method:"POST",body:form});acceptProject(d.project);
    const failures=d.results.filter(r=>r.error);if(failures.length)setError(failures.map(r=>`${r.name}: ${r.error}`).join(" · "));else setNotice(`บันทึกไฟล์ต้นฉบับ ${d.results.length} ไฟล์แล้ว`);
  });if(fileInput.current)fileInput.current.value="";};
  const generate=async()=>{if(!project)return;await perform("script",async()=>{
    const p=dirty?await save():project;if(!p)return;
    const d=await api<{project:Project;notice:string}>(`/api/projects/${p.id}/script`,{method:"POST",body:body({revision:p.revision})});acceptProject(d.project);setSelected(d.project.scenes[0]?.id||null);setNotice(d.notice);setStep("script");
  });};
  const createJob=async()=>{if(!project)return;await perform("prepare",async()=>{const p=dirty?await save():project;if(!p)return;const d=await api<{job:JobSummary;prompt:string}>(`/api/projects/${p.id}/jobs`,{method:"POST"});setJobs(prev=>[d.job,...prev]);setJobPrompt(d.prompt);setNotice("เตรียมงานแล้ว คัดลอกคำสั่งไปแชต Codex เพื่อเริ่มตัดต่อ");});};
  const copy=async(text:string)=>{try{await navigator.clipboard.writeText(text);setNotice("คัดลอกแล้ว");}catch{setError("คัดลอกอัตโนมัติไม่ได้ เลือกและคัดลอกข้อความในช่องด้วยตนเอง");}};
  const activeScene=project?.scenes.find(s=>s.id===selected)||project?.scenes[0];
  const preview=project?.assets.find(a=>a.id===(previewId||activeScene?.assetId))||project?.assets.find(a=>a.kind!=="audio");
  const latestJob=jobs[0];
  const checks=project?readiness(project):[];
  const ready=checks.every(c=>c.ok||c.optional);
  const audio=project?.assets.find(a=>a.id===project.voiceAssetId);
  const total=project?.scenes.reduce((s,c)=>s+c.duration,0)||0;
  const filtered=projects.filter(p=>p.archived===showArchived&&p.name.toLowerCase().includes(query.toLowerCase()));

  return <div className="min-h-screen">
    <a href="#workspace" className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-50 focus:rounded-xl focus:bg-primary focus:p-3 focus:text-primary-content">ข้ามไปพื้นที่ทำงาน</a>
    <header className="border-b border-base-300/60 bg-base-100">
      <div className="navbar mx-auto max-w-[1440px] gap-3 px-4 sm:px-6">
        <button className="btn btn-ghost btn-square lg:hidden" aria-label="เปิดรายการโปรเจกต์" onClick={()=>setMobileProjects(!mobileProjects)}><Menu className="size-5"/></button>
        <button className="flex items-center gap-2.5 text-lg font-semibold tracking-tight" onClick={()=>setHelp(false)} aria-label="กลับสตูดิโอ shopee_gpt"><span className="flex size-8 items-center justify-center rounded-xl bg-primary text-primary-content"><Clapperboard className="size-4"/></span>shopee<span className="text-base-content/60">_gpt</span><span className="badge badge-ghost badge-sm ml-2 hidden font-normal sm:flex">Studio</span></button>
        <div className="ml-auto flex items-center gap-1 sm:gap-3">
          <span className="hidden items-center gap-2 text-xs text-base-content/65 md:flex"><span className="status status-success status-xs"/>พื้นที่ทำงานส่วนตัว</span>
          <ErrorCenter/><button className={`btn btn-ghost btn-sm ${help?"btn-active":""}`} onClick={()=>setHelp(!help)}><HelpCircle className="size-4"/><span className="hidden sm:inline">การเชื่อมต่อ</span></button>
          <button className="btn btn-ghost btn-square btn-sm" aria-label={light?"ใช้โหมดมืด":"ใช้โหมดสว่าง"} onClick={()=>{const v=!light;setLight(v);localStorage.setItem("studio.theme",v?"light":"dark");document.documentElement.dataset.theme=v?"light":"dark";}}>{light?<Moon className="size-4"/>:<Sun className="size-4"/>}</button>
        </div>
      </div>
    </header>
    <div className="mx-auto flex max-w-[1440px]">
      <aside className={`${mobileProjects?"fixed inset-x-0 top-16 bottom-0 z-30 flex":"hidden"} w-full shrink-0 flex-col border-r border-base-300/50 bg-base-100 p-4 lg:sticky lg:top-0 lg:flex lg:h-[calc(100vh-65px)] lg:w-60`} aria-label="โปรเจกต์">
        <div className="mb-5 flex items-center justify-between"><h2 className="text-sm font-semibold">โปรเจกต์ของคุณ</h2><button className="btn btn-ghost btn-square btn-xs lg:hidden" aria-label="ปิดรายการโปรเจกต์" onClick={()=>setMobileProjects(false)}><X className="size-4"/></button></div>
        <button className="btn btn-primary btn-sm mb-4 w-full" onClick={openNew} disabled={!!busy}><Plus className="size-4"/>สร้างโปรเจกต์</button>
        <label className="input input-sm mb-4 w-full"><Search className="size-4 opacity-60"/><input aria-label="ค้นหาโปรเจกต์" placeholder="ค้นหาสินค้า..." value={query} onChange={e=>setQuery(e.target.value)}/></label>
        <div className="flex-1 space-y-1 overflow-y-auto">
          {loading?<div className="space-y-3"><div className="skeleton h-16"/><div className="skeleton h-16"/></div>:filtered.length?filtered.map(p=><button key={p.id} className={`flex w-full items-center gap-3 rounded-xl p-2.5 text-left transition-colors ${project?.id===p.id?"bg-primary/15 text-base-content":"hover:bg-base-200"}`} onClick={()=>void choose(p.id)} disabled={!!busy}>
            <MediaThumb asset={p.assets.find(a=>a.kind!=="audio")} className="size-10"/><span className="min-w-0"><span className="line-clamp-2 text-xs font-medium leading-relaxed">{p.name}</span><span className="mt-1 block text-[11px] text-base-content/65">{p.archived?"เก็บในคลัง":statusText[p.status]}</span></span>
          </button>):<p className="px-2 py-6 text-center text-xs leading-relaxed text-base-content/60">{query?"ไม่พบโปรเจกต์ที่ค้นหา":showArchived?"ยังไม่มีโปรเจกต์ในคลัง":"โปรเจกต์แรกของคุณเริ่มที่นี่"}</p>}
        </div>
        <div className="mt-5 border-t border-base-300/60 pt-4"><button className="btn btn-ghost btn-sm w-full justify-start font-normal" onClick={()=>setShowArchived(!showArchived)}><Archive className="size-4"/>{showArchived?"กลับโปรเจกต์ปัจจุบัน":"คลังโปรเจกต์"}<span className="ml-auto text-xs">{projects.filter(p=>p.archived).length}</span></button><p className="mt-3 px-3 text-[11px] leading-relaxed text-base-content/60">ต้นฉบับอยู่บนเครื่องคุณ<br/>ส่งไฟล์ไป CapCut เมื่อเริ่มงานเท่านั้น</p></div>
      </aside>
      <main id="workspace" className="min-w-0 flex-1 p-4 sm:p-6 lg:p-8">
        {error&&<div role="alert" className="alert alert-error alert-soft mb-5 flex items-start text-sm"><span className="flex-1 leading-relaxed">{error}</span><button className="btn btn-ghost btn-square btn-xs" aria-label="ปิดข้อความผิดพลาด" onClick={()=>setError("")}><X className="size-4"/></button></div>}
        {help?<ConnectionGuide health={health} busy={!!busy} refresh={()=>void perform("health",async()=>{setHealth(await api<Health>("/api/health?refresh=1"));setNotice("ตรวจสถานะเครื่องมือแล้ว");})} close={()=>setHelp(false)}/>:loading?<div className="space-y-6" aria-label="กำลังโหลดโปรเจกต์"><div className="skeleton h-10 w-1/2"/><div className="skeleton h-14"/><div className="skeleton h-96"/></div>:!project?<div className="mx-auto max-w-3xl py-10 sm:py-20">
          <div className="mb-8 flex size-14 items-center justify-center rounded-2xl bg-primary/15 text-primary"><Video className="size-7" strokeWidth={1.5}/></div>
          <h1 className="max-w-xl text-3xl leading-snug font-semibold sm:text-4xl">ของที่คุณใช้จริง<br/><span className="text-base-content/65">มีเรื่องดี ๆ ให้เล่า</span></h1>
          <p className="mt-5 max-w-lg text-sm leading-loose text-base-content/70">รวมลิงก์สินค้า คลิปที่ถ่ายเอง และสิ่งที่คุณอยากบอก<br className="hidden sm:block"/>วางสคริปต์ จับคู่ช็อต แล้วตัดต่อเป็นโปรเจกต์ที่แก้ต่อได้ใน CapCut</p>
          <button className="btn btn-primary mt-8" onClick={openNew}><Plus className="size-4"/>เริ่มโปรเจกต์แรก<ArrowRight className="size-4"/></button>
          <div className="mt-16 grid gap-8 border-t border-base-300/60 pt-8 sm:grid-cols-3">{[{icon:Film,title:"ใช้ฟุตเทจที่คุณถ่าย",text:"ภาพและวิดีโออยู่ด้วยกัน จัดช็อตให้ตรงกับสิ่งที่พูด"},{icon:FileText,title:"เล่าอย่างมีหลักฐาน",text:"แยกข้อเท็จจริงกับประสบการณ์จริง ปรับบทได้ทุกซีน"},{icon:Clapperboard,title:"ตัดต่อใน CapCut",text:"ส่ง brief และไฟล์ต้นฉบับให้ Codex สร้าง draft ที่แก้ต่อได้"}].map(item=><div key={item.title}><item.icon className="mb-4 size-5 text-primary"/><h2 className="text-sm font-medium">{item.title}</h2><p className="mt-2 text-xs leading-loose text-base-content/65">{item.text}</p></div>)}</div>
        </div>:<>
          <div className="mb-6 flex flex-wrap items-start justify-between gap-4">
            <div className="min-w-0 flex-1"><div className="mb-3 flex flex-wrap items-center gap-2 text-xs text-base-content/65"><FolderOpen className="size-3.5"/><span>โปรเจกต์</span><span>/</span><span className="badge badge-ghost badge-sm">{project.archived?"ในคลัง":statusText[project.status]}</span></div><h1 className="max-w-2xl text-2xl leading-snug font-semibold">{project.name}</h1><p className="mt-2 text-xs text-base-content/65">{project.platform === "shopee"?"Shopee Video":project.platform === "tiktok"?"TikTok":"Instagram Reels"} · 9:16 · {project.duration} วินาที · {project.assets.filter(a=>a.kind==="video").length} วิดีโอต้นฉบับ</p></div>
            <div className="flex items-center gap-2"><span className="hidden text-xs text-base-content/65 sm:block" aria-live="polite">{dirty?"มีการแก้ไขที่ยังไม่บันทึก":"บันทึกแล้ว"}</span><button className="btn btn-outline btn-sm" disabled={!dirty||!!busy} onClick={()=>void perform("save",async()=>{await save();setNotice("บันทึกแล้ว");})}>{busy==="save"?<Spinner/>:<Save className="size-4"/>}บันทึก</button><div className="dropdown dropdown-end"><button tabIndex={0} className="btn btn-ghost btn-square btn-sm" aria-label="เมนูโปรเจกต์"><MoreHorizontal className="size-5"/></button><ul tabIndex={0} className="menu dropdown-content z-20 mt-2 w-52 rounded-2xl border border-base-300 bg-base-100 p-2 shadow-sm"><li><button disabled={!!busy} onClick={()=>archiveDialog.current?.showModal()}><Archive className="size-4"/>{project.archived?"กู้คืนโปรเจกต์":"เก็บเข้าคลัง"}</button></li><li><button disabled={!!busy} onClick={()=>void perform("reload",async()=>{if(!dirty||window.confirm("ทิ้งการแก้ไขที่ยังไม่บันทึกแล้วโหลดข้อมูลล่าสุด?"))await loadProject(project.id);})}><RefreshCw className="size-4"/>โหลดข้อมูลล่าสุด</button></li></ul></div></div>
          </div>
          {project.archived&&<div className="alert alert-info alert-soft mb-5 text-sm">โปรเจกต์นี้อยู่ในคลัง กู้คืนจากเมนูโปรเจกต์เพื่อเริ่มงาน CapCut ใหม่</div>}
          <nav aria-label="ขั้นตอนผลิตคลิป" className="mb-7 overflow-x-auto border-b border-base-300/60"><div role="tablist" className="tabs tabs-border flex w-max min-w-full gap-1">{steps.map((s,i)=><button key={s.id} role="tab" aria-selected={step===s.id} className={`tab gap-2 whitespace-nowrap px-3 text-xs sm:px-4 sm:text-sm ${step===s.id?"tab-active text-primary":"text-base-content/65"}`} onClick={()=>{setStep(s.id);setPreviewId(null);}}><span className={`flex size-5 items-center justify-center rounded-full text-[10px] ${step===s.id?"bg-primary text-primary-content":"bg-base-300/50"}`}>{i+1}</span>{s.label}</button>)}</div></nav>
          <div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_280px]">
            <section className="min-w-0" aria-label={steps.find(s=>s.id===step)?.label}><fieldset disabled={!!busy} className="min-w-0">
              {step==="product"&&<div className="space-y-6">
                <div><h2 className="text-lg font-semibold">เริ่มจากข้อมูลที่เชื่อถือได้</h2><p className="mt-2 text-sm leading-relaxed text-base-content/65">ราคาและรายละเอียดจากร้าน ส่วนประสบการณ์มาจากคุณ</p></div>
                <Field label="ชื่อสินค้า"><input className="input w-full" aria-label="ชื่อสินค้า" value={project.name} maxLength={240} onChange={e=>edit({name:e.target.value,verified:false})}/></Field>
                <div className="grid gap-4 sm:grid-cols-[1fr_160px]"><Field label="ลิงก์สินค้า / Affiliate" hint="เก็บลิงก์เดิมพร้อมรหัส Affiliate ไม่ตัด query ทิ้ง"><input className="input w-full" aria-label="ลิงก์สินค้า" value={project.link} placeholder="https://shopee.co.th/..." onChange={e=>edit({link:e.target.value,verified:false})}/></Field><Field label="ราคา ณ วันที่บันทึก"><input className="input w-full" aria-label="ราคา" placeholder="เช่น 590" value={project.price} onChange={e=>edit({price:e.target.value,verified:false})}/></Field></div>
                <Field label="ข้อเท็จจริงจากสินค้า" hint="ระบุรุ่น วัสดุ ขนาด หรือคุณสมบัติที่ตรวจแล้ว หลีกเลี่ยงคำกล่าวอ้างที่ไม่มีหลักฐาน"><textarea className="textarea min-h-28 w-full" aria-label="ข้อเท็จจริงจากสินค้า" placeholder="เช่น รุ่น 1.5 ลิตร ปรับอุณหภูมิได้ มีระบบตัดไฟ..." value={project.facts} onChange={e=>edit({facts:e.target.value,verified:false})}/></Field>
                <Field label="สิ่งที่คุณพบจากการใช้จริง" hint="เล่าทั้งข้อดีและข้อจำกัด ระบบจะไม่แต่งประสบการณ์แทนคุณ"><textarea className="textarea min-h-28 w-full" aria-label="ประสบการณ์ใช้จริง" placeholder="ลองใช้กับอะไร เห็นผลอย่างไร มีข้อสังเกตอะไรบ้าง..." value={project.experience} onChange={e=>edit({experience:e.target.value})}/></Field>
                <div className="grid gap-4 sm:grid-cols-2"><Field label="แนวทางเล่าเรื่อง"><select className="select w-full" aria-label="แนวทางเล่าเรื่อง" value={project.tone} onChange={e=>edit({tone:e.target.value as Project["tone"]})}><option value="honest">รีวิวตรงไปตรงมา</option><option value="tutorial">สาธิตวิธีใช้</option><option value="problem">ปัญหา → วิธีแก้</option><option value="unboxing">แกะกล่องและลองใช้</option></select></Field><Field label="กลุ่มคนดู"><input className="input w-full" aria-label="กลุ่มคนดู" value={project.audience} onChange={e=>edit({audience:e.target.value})}/></Field></div>
                <div className="grid gap-4 sm:grid-cols-2"><Field label="ช่องทางเผยแพร่"><select className="select w-full" aria-label="ช่องทาง" value={project.platform} onChange={e=>edit({platform:e.target.value as Project["platform"]})}><option value="shopee">Shopee Video</option><option value="tiktok">TikTok</option><option value="reels">Instagram Reels</option></select></Field><Field label="ความยาวเป้าหมาย"><select className="select w-full" aria-label="ความยาวเป้าหมาย" value={project.duration} onChange={e=>edit({duration:Number(e.target.value)})}>{[15,30,45,60,90].map(s=><option value={s} key={s}>{s} วินาที</option>)}</select></Field></div>
                <label className="flex cursor-pointer items-start gap-3 rounded-xl bg-base-100 p-4"><input type="checkbox" className="checkbox checkbox-primary checkbox-sm mt-0.5" checked={project.verified} onChange={e=>edit({verified:e.target.checked})}/><span><span className="block text-sm font-medium">ตรวจชื่อ ราคา และรายละเอียดแล้ว</span><span className="mt-1 block text-xs leading-relaxed text-base-content/65">ตรวจอีกครั้งก่อนโพสต์ เพราะราคาและโปรโมชันอาจเปลี่ยนได้</span></span></label>
                <div className="flex justify-end"><button className="btn btn-primary" onClick={()=>setStep("media")}>เพิ่มฟุตเทจจริง<ArrowRight className="size-4"/></button></div>
              </div>}
              {step==="media"&&<div className="space-y-6">
                <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">ฟุตเทจของเรื่องนี้</h2><p className="mt-2 text-sm text-base-content/65">{project.assets.filter(a=>a.kind!=="audio").length} ภาพและวิดีโอ · คลิกไฟล์เพื่อดูต้นฉบับ</p></div><button className="btn btn-primary btn-sm" disabled={!!busy} onClick={()=>fileInput.current?.click()}>{busy==="upload"?<Spinner/>:<Upload className="size-4"/>}เพิ่มไฟล์</button></div>
                <div className="rounded-2xl border border-dashed border-base-content/25 px-5 py-7 text-center" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(!busy)void upload(e.dataTransfer.files);}}><Upload className="mx-auto mb-3 size-5 text-base-content/60"/><p className="text-sm">ลากวิดีโอหรือรูปสินค้ามาวาง</p><p className="mt-2 text-xs leading-relaxed text-base-content/65">MP4 / MOV / WebM / JPG / PNG / WebP<br/>ไม่เกิน 200 MB ต่อไฟล์ · 500 MB ต่อครั้ง</p><button className="btn btn-ghost btn-sm mt-3" disabled={!!busy} onClick={()=>fileInput.current?.click()}>หรือเลือกไฟล์จากเครื่อง</button></div>
                {!project.assets.some(a=>a.kind!=="audio")?<Empty title="ยังไม่มีฟุตเทจต้นฉบับ" description="เพิ่มคลิปเปิดกล่อง สาธิตการใช้ หรือภาพสินค้า เริ่มจากคลิปสั้น ๆ ที่เห็นการใช้งานชัดเจน"/>:<div className="grid grid-cols-2 gap-4 sm:grid-cols-3">{project.assets.filter(a=>a.kind!=="audio").map(a=><div key={a.id} className={`overflow-hidden rounded-2xl border ${preview?.id===a.id?"border-primary":"border-base-300/70"} bg-base-100`}><button className="block w-full" aria-label={`พรีวิว ${a.name}`} onClick={()=>setPreviewId(a.id)}><MediaThumb asset={a} className="aspect-[4/3] w-full rounded-none"/></button><div className="space-y-2 p-3"><p className="truncate text-xs font-medium" title={a.name}>{a.name}</p><p className="text-[11px] text-base-content/65">{fileSize(a.size)} · {a.width&&a.height?`${a.width}×${a.height}`:a.mime}</p><div className="flex items-center gap-1"><select className="select select-xs min-w-0 flex-1" aria-label={`บทบาทของ ${a.name}`} value={a.role} disabled={!!busy} onChange={e=>void perform("role",async()=>{const d=await api<{asset:Asset}>(`/api/assets/${a.id}`,{method:"PATCH",body:body({role:e.target.value})});setProject(p=>p?{...p,assets:p.assets.map(x=>x.id===a.id?d.asset:x)}:p);})}>{["hook","demo","detail","cta"].map(r=><option key={r} value={r}>{roleText[r]}</option>)}</select><button className="btn btn-ghost btn-square btn-xs" aria-label={`นำ ${a.name} ออกจากโปรเจกต์`} disabled={!!busy} onClick={()=>void perform("delete",async()=>{if(!window.confirm(`นำ ${a.name} ออกจากโปรเจกต์? ไฟล์ในระบบจะถูกลบ`))return;if(dirty)await save();await api(`/api/assets/${a.id}`,{method:"DELETE"});const d=await api<{project:Project}>(`/api/projects/${project.id}`);acceptProject(d.project);setPreviewId(null);})}><Trash2 className="size-3.5"/></button></div></div></div>)}</div>}
                <label className="flex items-start gap-3 text-sm"><input className="checkbox checkbox-primary checkbox-sm mt-0.5" type="checkbox" checked={project.rightsConfirmed} onChange={e=>edit({rightsConfirmed:e.target.checked})}/><span>ฉันมีสิทธิ์ใช้ภาพ วิดีโอ และเสียงเหล่านี้<br/><span className="text-xs text-base-content/65">เมื่อตัดต่อจะอัปโหลดเฉพาะไฟล์ที่เลือกใช้ไปยัง CapCut</span></span></label>
                <div className="flex justify-end"><button className="btn btn-primary" disabled={!!busy||!project.assets.some(a=>a.kind!=="audio")} onClick={()=>project.scenes.length?setStep("script"):void generate()}>{busy==="script"?<Spinner/>:<FileText className="size-4"/>}{project.scenes.length?"ไปสคริปต์":"วางโครงสคริปต์"}<ArrowRight className="size-4"/></button></div>
              </div>}
              {step==="script"&&<div className="space-y-5">
                <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">สคริปต์และช็อตที่เล่าเรื่อง</h2><p className="mt-2 text-xs leading-relaxed text-base-content/65">{project.scenes.length} ซีน · {total.toFixed(1)} วินาที{project.scenes.length>0&&` · ${project.scriptSource==="gemini"?"สร้างด้วย Gemini":project.scriptSource==="template"?"โครงสคริปต์ที่แก้ไขได้":"เขียนเอง"}`}</p></div><button className="btn btn-outline btn-sm" disabled={!!busy} onClick={()=>{if(project.scenes.length&&!window.confirm("สร้างสคริปต์ใหม่แทนบทเดิม? ไฟล์เสียงเดิมจะไม่ถูกเลือกใช้อีก"))return;void generate();}}>{busy==="script"?<Spinner/>:<Sparkles className="size-4"/>}{project.scenes.length?"วางโครงใหม่":"วางโครงสคริปต์"}</button></div>
                {!project.scenes.length?<Empty title="เริ่มเล่าเรื่องจากคลิปของคุณ" description="สร้างโครงเรื่องเปิดคลิป สาธิต จุดที่ควรรู้ และปิดท้าย จากนั้นปรับบทให้ตรงกับสิ่งที่เห็นจริง"><button className="btn btn-primary" disabled={!!busy} onClick={()=>void generate()}><Sparkles className="size-4"/>สร้างโครงสคริปต์</button></Empty>:<>
                  {project.scriptSource==="template"&&<div className="alert alert-info alert-soft py-3 text-xs leading-relaxed text-base-content">นี่คือโครงสคริปต์ ไม่ใช่ผลวิเคราะห์วิดีโอ กรุณาแก้บทให้ตรงคลิปและตัดข้อความที่ไม่มีหลักฐาน</div>}
                  <div className="space-y-4">{project.scenes.map((s,index)=>{
                    const a=project.assets.find(a=>a.id===s.assetId);
                    const tooShort=a?.kind==="video"&&a.duration!==null&&s.inPoint+s.duration>a.duration+.1;
                    if(selected!==s.id) return <button key={s.id} className="flex w-full items-center gap-3 rounded-2xl border border-base-300/60 bg-base-100 p-4 text-left transition-colors hover:border-base-content/30 sm:gap-4" onClick={()=>{setSelected(s.id);setPreviewId(s.assetId);}} aria-label={`แก้ไขซีน ${index+1}: ${s.title}`}><MediaThumb asset={a} className="h-16 w-20 sm:h-20 sm:w-24"/><span className="min-w-0 flex-1"><span className="mb-2 flex flex-wrap items-center gap-2"><span className="text-sm font-medium">{index+1}. {s.title}</span><span className="badge badge-ghost badge-xs tabular-nums">{s.duration}s</span></span><span className="line-clamp-2 text-xs leading-relaxed text-base-content/70">{s.narration||"เพิ่มบทพูดในซีนนี้"}</span>{!a&&<span className="mt-1 block text-[11px] text-warning">ยังไม่เลือกฟุตเทจ</span>}{tooShort&&<span className="mt-1 block text-[11px] text-warning">ช่วงเวลาเกินความยาวคลิป</span>}</span><ChevronDown className="size-4 shrink-0 text-base-content/50"/></button>;
                    return <article id={`scene-${s.id}`} key={s.id} className={`rounded-2xl border bg-base-100 p-4 transition-colors ${selected===s.id?"border-primary/70":"border-base-300/60"}`} onFocusCapture={()=>{setSelected(s.id);setPreviewId(null);}}>
                      <div className="mb-4 flex items-center gap-3"><span className="flex size-7 items-center justify-center rounded-lg bg-base-300/60 text-xs tabular-nums">{index+1}</span><input className="input input-ghost input-sm min-w-0 flex-1 px-1 font-medium" aria-label={`ชื่อซีน ${index+1}`} value={s.title} onChange={e=>editScene(s.id,{title:e.target.value})}/><div className="flex"><button className="btn btn-ghost btn-square btn-xs" aria-label={`เลื่อนซีน ${index+1} ขึ้น`} disabled={index===0||!!busy} onClick={()=>{const scenes=[...project.scenes];[scenes[index-1],scenes[index]]=[scenes[index],scenes[index-1]];edit({scenes,voiceAssetId:null});}}><ChevronUp className="size-3.5"/></button><button className="btn btn-ghost btn-square btn-xs" aria-label={`เลื่อนซีน ${index+1} ลง`} disabled={index===project.scenes.length-1||!!busy} onClick={()=>{const scenes=[...project.scenes];[scenes[index+1],scenes[index]]=[scenes[index],scenes[index+1]];edit({scenes,voiceAssetId:null});}}><ChevronDown className="size-3.5"/></button><button className="btn btn-ghost btn-square btn-xs" aria-label={`ลบซีน ${index+1}`} disabled={!!busy} onClick={()=>edit({scenes:project.scenes.filter(x=>x.id!==s.id),voiceAssetId:null})}><X className="size-3.5"/></button></div></div>
                      <div className="grid gap-4 sm:grid-cols-[minmax(0,1fr)_160px]"><div className="space-y-3"><Field label="บทพูด"><textarea className="textarea min-h-24 w-full text-sm leading-loose" aria-label={`บทพูดซีน ${index+1}`} value={s.narration} maxLength={2500} onChange={e=>editScene(s.id,{narration:e.target.value})}/></Field><Field label="ข้อความบนจอ"><input className="input input-sm w-full" aria-label={`ข้อความบนจอซีน ${index+1}`} value={s.overlay} maxLength={200} placeholder="สั้น กระชับ อ่านทัน" onChange={e=>editScene(s.id,{overlay:e.target.value})}/></Field></div><div className="space-y-3"><button className="block w-full" aria-label={`ดูช็อตซีน ${index+1}`} onClick={()=>{setSelected(s.id);setPreviewId(s.assetId);}}><MediaThumb asset={a} className="aspect-video w-full"/></button><Field label="ฟุตเทจที่ใช้"><select className="select select-sm w-full text-xs" aria-label={`ฟุตเทจซีน ${index+1}`} value={s.assetId||""} onChange={e=>{editScene(s.id,{assetId:e.target.value||null,inPoint:0});setPreviewId(e.target.value||null);}}><option value="">เลือกฟุตเทจ...</option>{project.assets.filter(a=>a.kind!=="audio").map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-2"><Field label="เริ่ม (วิ)"><input className="input input-sm w-full text-xs" type="number" min={0} step={.1} aria-label={`เวลาเริ่มซีน ${index+1}`} value={s.inPoint} onChange={e=>editScene(s.id,{inPoint:Number(e.target.value)})}/></Field><Field label="ยาว (วิ)"><input className="input input-sm w-full text-xs" type="number" min={1} max={60} step={.1} aria-label={`ความยาวซีน ${index+1}`} value={s.duration} onChange={e=>editScene(s.id,{duration:Number(e.target.value)})}/></Field></div></div></div>
                      <div className="mt-3 flex items-start gap-2 text-xs leading-relaxed text-base-content/65"><Video className="mt-0.5 size-3.5 shrink-0"/><input className="input input-ghost input-xs h-auto min-h-6 w-full p-0 text-xs" aria-label={`แนวภาพซีน ${index+1}`} value={s.shot} onChange={e=>editScene(s.id,{shot:e.target.value})}/></div>
                      {tooShort&&<p className="mt-3 text-xs text-warning">ช่วงที่เลือกเกินความยาวคลิป ({a.duration!.toFixed(1)} วินาที) ลดเวลาหรือเลือกฟุตเทจใหม่</p>}
                      {a&&<a href="#source-preview" className="btn btn-outline btn-sm mt-4 w-full xl:hidden"><Video className="size-4"/>ดูต้นฉบับของซีนนี้<ArrowRight className="size-4"/></a>}
                    </article>;
                  })}</div>
                  <button className="btn btn-ghost btn-sm" disabled={project.scenes.length>=20||!!busy} onClick={()=>edit({scenes:[...project.scenes,{id:crypto.randomUUID(),role:"demo",title:"ซีนใหม่",narration:"",overlay:"",shot:"",duration:5,inPoint:0,assetId:null}],voiceAssetId:null})}><Plus className="size-4"/>เพิ่มซีน</button>
                  <div className="border-t border-base-300/60 pt-5"><h3 className="mb-3 text-sm font-medium">ลำดับเรื่อง</h3><div className="flex gap-3 overflow-x-auto pb-3">{project.scenes.map((s,i)=><button key={s.id} className={`w-24 shrink-0 rounded-xl text-left ${selected===s.id?"ring-2 ring-primary ring-offset-2 ring-offset-base-200":""}`} onClick={()=>{setSelected(s.id);setPreviewId(s.assetId);}}><MediaThumb asset={project.assets.find(a=>a.id===s.assetId)} className="aspect-video w-full"/><p className="mt-2 truncate text-[11px]">{i+1}. {s.title}</p><p className="mt-1 text-[10px] tabular-nums text-base-content/65">{s.duration}s</p></button>)}</div></div>
                  <div className="flex justify-end"><button className="btn btn-primary" onClick={()=>setStep("voice")}>เตรียมเสียงพากย์<ArrowRight className="size-4"/></button></div>
                </>}
              </div>}
              {step==="voice"&&<VoiceControls project={project} busy={busy} ai={!!health?.ai} edge={!!health?.voice} edit={edit} save={save} accept={acceptProject} run={perform} upload={()=>fileInput.current?.click()} next={()=>setStep("capcut")} notice={setNotice}/>}
              {step==="capcut"&&<div className="space-y-6"><div><h2 className="text-lg font-semibold">พร้อมให้เรื่องนี้เป็นคลิป</h2><p className="mt-2 text-sm leading-relaxed text-base-content/65">ส่งเฉพาะช็อตที่เลือก พร้อมบทและเสียง ไปสร้าง draft ใน CapCut</p></div>
                <div className="divide-y divide-base-300/50 rounded-2xl bg-base-100 px-5">{checks.map(c=><div key={c.key} className="flex items-center gap-3 py-4">{c.ok?<CheckCircle2 className="size-4 shrink-0 text-success"/>:<Circle className={`size-4 shrink-0 ${c.optional?"text-base-content/40":"text-warning"}`}/>}<span className="flex-1 text-sm">{c.label}</span>{c.optional&&!c.ok&&<span className="text-[11px] text-base-content/55">แนะนำ</span>}</div>)}</div>
                <Field label="ข้อความโพสต์ / Caption"><textarea className="textarea min-h-36 w-full text-sm leading-relaxed" aria-label="ข้อความโพสต์" value={project.caption} onChange={e=>edit({caption:e.target.value})}/></Field>
                <div className="flex flex-wrap gap-3"><button className="btn btn-primary" disabled={!!busy||!ready||project.archived||jobs.some(j=>["prepared","running"].includes(j.state))} onClick={()=>void createJob()}>{busy==="prepare"?<Spinner/>:<Clapperboard className="size-4"/>}เตรียมงานให้ Codex</button><button className="btn btn-outline" disabled={!!busy} onClick={()=>void perform("export",async()=>{const p=dirty?await save():project;if(p){window.location.assign(`/api/projects/${p.id}/export`);setNotice("กำลังดาวน์โหลดแพ็กเกจ พร้อมไฟล์ที่เลือกใช้และ brief");}})}><ArrowDownToLine className="size-4"/>แพ็กเกจต้นฉบับ</button></div>
                <p className="text-xs leading-relaxed text-base-content/65">แพ็กเกจคือไฟล์ต้นฉบับและคำสั่งตัดต่อ ไม่ใช่ CapCut draft สำเร็จ เวลาซับใน SRT เป็นค่าประมาณจนกว่าจะจัดตามเสียงจริง</p>
                {latestJob&&<div className="rounded-2xl border border-base-300/70 bg-base-100 p-5"><div className="mb-3 flex items-center justify-between gap-3"><h3 className="text-sm font-semibold">งาน CapCut ล่าสุด</h3><span className={`badge badge-sm ${latestJob.state==="completed"?"badge-success badge-soft":latestJob.state==="failed"?"badge-warning badge-soft":"badge-ghost"}`}>{jobText[latestJob.state]}</span></div><p className="text-xs leading-loose text-base-content/70" aria-live="polite">{latestJob.message}</p>
                  {latestJob.state==="running"&&<progress className="progress progress-primary mt-4 h-1.5 w-full"/>}
                  {latestJob.state==="prepared"&&<div className="mt-5 space-y-4"><div className="flex flex-wrap gap-2"><button className="btn btn-primary btn-sm" disabled={!!busy} onClick={()=>void perform("copy",async()=>{const d=await api<{prompt:string}>(`/api/jobs/${latestJob.id}`);setJobPrompt(d.prompt);await copy(d.prompt);})}><Copy className="size-4"/>คัดลอกคำสั่งไป Codex</button><button className="btn btn-outline btn-sm" disabled={!!busy||!health?.capcut.installed} onClick={()=>void perform("start",async()=>{await api(`/api/jobs/${latestJob.id}`,{method:"POST",body:body({action:"start"})});await new Promise(r=>setTimeout(r,800));const d=await api<{job:JobSummary}>(`/api/jobs/${latestJob.id}`);setJobs(prev=>[d.job,...prev.slice(1)]);setNotice("เริ่มตัวเชื่อม CLI แล้ว หากต้องอนุญาตบัญชีหรือโต้ตอบ ให้ทำต่อในแชต Codex");})}><Sparkles className="size-4"/>ลองตัวเชื่อมอัตโนมัติ</button></div><p className="text-xs leading-relaxed text-base-content/65">วิธีหลัก: วางคำสั่งในแชต Codex ที่ติดตั้ง CapCut แล้ว เพื่อดูพรีวิวและตอบขั้นตอนที่ต้องโต้ตอบ ตัวเชื่อมอัตโนมัติใช้ได้กับงานที่ปลั๊กอินทำผ่าน CLI ได้เท่านั้น</p>
                    {jobPrompt&&<details className="collapse collapse-arrow border border-base-300/60"><summary className="collapse-title min-h-10 py-3 text-xs">ดูคำสั่งที่เตรียมไว้</summary><div className="collapse-content"><textarea className="textarea min-h-36 w-full text-xs" aria-label="คำสั่งสำหรับ Codex" readOnly value={jobPrompt}/></div></details>}
                    <details className="collapse collapse-arrow border border-base-300/60"><summary className="collapse-title min-h-10 py-3 text-xs">บันทึกผลจาก CapCut ด้วยตนเอง</summary><div className="collapse-content space-y-3"><p className="text-xs leading-relaxed text-base-content/65">ใช้ draft ID และลิงก์ editor ที่ CapCut ส่งกลับมาจริง ระบบจะระบุว่าเป็นผลที่คุณยืนยัน</p><input className="input input-sm w-full" aria-label="CapCut draft ID" placeholder="Draft ID จาก CapCut" value={manualDraft} onChange={e=>setManualDraft(e.target.value)}/><input className="input input-sm w-full" aria-label="CapCut editor URL" placeholder="https://www.capcut.com/editor/..." value={manualUrl} onChange={e=>setManualUrl(e.target.value)}/><button className="btn btn-outline btn-sm" disabled={!!busy||!manualUrl||!manualDraft} onClick={()=>void perform("complete",async()=>{await api(`/api/jobs/${latestJob.id}`,{method:"POST",body:body({action:"complete",draftId:manualDraft,editUrl:manualUrl})});await loadProject(project.id);setStep("capcut");setNotice("บันทึกลิงก์แล้ว กรุณาเปิดตรวจ draft");})}>บันทึกลิงก์ draft</button></div></details>
                  </div>}
                  {["prepared","running"].includes(latestJob.state)&&<button className="btn btn-ghost btn-sm mt-4 text-base-content/65" disabled={!!busy} onClick={()=>void perform("cancel",async()=>{await api(`/api/jobs/${latestJob.id}`,{method:"POST",body:body({action:"cancel"})});await loadProject(project.id);setStep("capcut");})}>ยกเลิกการรอผล</button>}
                  {latestJob.draftUrl&&<a className="btn btn-primary btn-sm mt-4" href={latestJob.draftUrl} target="_blank" rel="noopener noreferrer">เปิด draft ใน CapCut<ExternalLink className="size-4"/></a>}
                </div>}
                {project.capcutUrl&&<div className="flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-primary/10 p-5"><div><h3 className="text-sm font-medium">ตรวจภาพ เสียง และข้อความก่อนเผยแพร่</h3><p className="mt-1 text-xs text-base-content/65">การมี draft ยังไม่ได้แปลว่าส่งออกวิดีโอหรือโพสต์แล้ว</p></div><button className="btn btn-outline btn-sm" disabled={!!busy||project.status==="done"} onClick={()=>void perform("done",async()=>{const p=dirty?await save():project;if(!p)return;const d=await api<{project:Project}>(`/api/projects/${p.id}`,{method:"PATCH",body:body({revision:p.revision,patch:{status:"done"}})});acceptProject(d.project);})}><Check className="size-4"/>{project.status==="done"?"ตรวจงานแล้ว":"ยืนยันตรวจงานแล้ว"}</button></div>}
                {jobs.length>1&&<details className="collapse collapse-arrow border border-base-300/60"><summary className="collapse-title text-sm">ประวัติงานก่อนหน้า ({jobs.length-1})</summary><div className="collapse-content divide-y divide-base-300">{jobs.slice(1).map(j=><div key={j.id} className="py-3 text-xs"><p>{jobText[j.state]} · {new Date(j.createdAt).toLocaleString("th-TH")}</p><p className="mt-1 text-base-content/65">{j.message}</p>{j.draftUrl&&<a className="link link-primary mt-2 inline-block" href={j.draftUrl} target="_blank" rel="noopener noreferrer">เปิด draft</a>}</div>)}</div></details>}
              </div>}
            </fieldset></section>
            <aside className="space-y-5 xl:sticky xl:top-6" aria-label="พรีวิวและข้อมูลอ้างอิง">
              <div id="source-preview" className="scroll-mt-4 rounded-2xl border border-base-300/60 bg-base-100 p-4"><div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-medium">{step==="media"?"ไฟล์ต้นฉบับ":"ช็อตที่เลือก"}</h2><span className="badge badge-ghost badge-xs">ต้นฉบับ</span></div>
                <div className="flex aspect-[9/12] max-h-96 items-center justify-center overflow-hidden rounded-xl bg-neutral text-neutral-content">
                  {preview?.kind==="video"?<video ref={videoRef} key={`${preview.id}-${activeScene?.id}`} className="size-full object-contain" controls playsInline preload="metadata" poster={preview.thumbnail?`/api/assets/${preview.id}?thumb=1`:undefined} src={`/api/assets/${preview.id}`} onLoadedMetadata={e=>{if(activeScene?.assetId===preview.id)e.currentTarget.currentTime=activeScene.inPoint;}} onTimeUpdate={e=>{if(step==="script"&&activeScene?.assetId===preview.id&&e.currentTarget.currentTime>=activeScene.inPoint+activeScene.duration&&!e.currentTarget.paused)e.currentTarget.pause();}}/>:preview?.kind==="image"?<img alt={preview.name} src={`/api/assets/${preview.id}`} className="size-full object-contain"/>:<div className="px-5 text-center"><Film className="mx-auto mb-3 size-8 opacity-40"/><p className="text-xs leading-relaxed opacity-65">เพิ่มฟุตเทจจริง<br/>เพื่อเห็นภาพของเรื่องนี้</p></div>}
                </div><p className="mt-3 truncate text-xs text-base-content/70" title={preview?.name}>{preview?.name||"ยังไม่มีไฟล์ที่เลือก"}</p>{preview?.duration&&<p className="mt-1 text-[11px] tabular-nums text-base-content/70">ต้นฉบับ {fmtTime(preview.duration)}{activeScene?.assetId===preview.id?` · ใช้ ${activeScene.inPoint.toFixed(1)}–${(activeScene.inPoint+activeScene.duration).toFixed(1)}s`:""}</p>}<p className="mt-3 text-[11px] leading-relaxed text-base-content/70">นี่คือพรีวิวไฟล์ต้นฉบับ ผลตัดต่อจริงดูใน CapCut</p>
                {step==="script"&&activeScene&&<a className="btn btn-ghost btn-sm mt-3 w-full xl:hidden" href={`#scene-${activeScene.id}`}><ArrowLeft className="size-4"/>กลับไปซีนที่เลือก</a>}
              </div>
              <div className="px-1"><div className="mb-3 flex items-center gap-2"><ShieldCheck className={`size-4 ${project.verified?"text-success":"text-base-content/50"}`}/><h2 className="text-sm font-medium">ข้อมูลอ้างอิง</h2></div><dl className="space-y-3 text-xs"><div className="flex gap-3"><dt className="w-12 shrink-0 text-base-content/60">ราคา</dt><dd>{project.price?`${project.price} บาท`:"ยังไม่ระบุ"}</dd></div><div><dt className="mb-1.5 text-base-content/60">ข้อเท็จจริง</dt><dd className="line-clamp-4 leading-relaxed">{project.facts||"เพิ่มข้อมูลที่ตรวจสอบแล้วในแท็บข้อมูลสินค้า"}</dd></div></dl>{project.link&&/^https:\/\/(?:[a-z0-9-]+\.)*(?:shopee\.co\.th|shp\.ee)(?:\/|$)/i.test(project.link)&&<a className="link link-primary mt-3 inline-flex items-center gap-1 text-xs" href={project.link} target="_blank" rel="noopener noreferrer">ดูหน้าสินค้า<ExternalLink className="size-3"/></a>}</div>
              <div className="border-t border-base-300/60 px-1 pt-5"><div className="mb-3 flex items-center gap-2"><Clapperboard className="size-4"/><h2 className="text-sm font-medium">CapCut × Codex</h2></div><p className="text-xs leading-relaxed text-base-content/65">{health?.capcut.message||"กำลังตรวจเครื่องมือ..."}</p><button className="btn btn-outline btn-sm mt-3 w-full font-normal" onClick={()=>setHelp(true)}><Settings2 className="size-3.5"/>ตั้งค่าการเชื่อมต่อ</button></div>
              {events.length>0&&<details className="collapse collapse-arrow border-t border-base-300/60 rounded-none"><summary className="collapse-title px-1 text-xs">กิจกรรมล่าสุด</summary><div className="collapse-content space-y-3 px-1">{events.slice(0,5).map((e,i)=><div key={i}><p className="text-xs">{e.message}</p><p className="mt-1 text-[10px] text-base-content/55">{new Date(e.createdAt).toLocaleString("th-TH")}</p></div>)}</div></details>}
            </aside>
          </div>
        </>}
      </main>
    </div>
    <input ref={fileInput} className="hidden" type="file" multiple accept={step==="voice"?"audio/*":"video/mp4,video/quicktime,video/webm,image/jpeg,image/png,image/webp"} aria-label="อัปโหลดไฟล์ต้นฉบับ" onChange={e=>void upload(e.target.files)}/>
    <dialog ref={newDialog} className="modal"><div className="modal-box max-w-xl rounded-2xl"><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-semibold">เริ่มเรื่องใหม่</h2><p className="mt-2 text-xs text-base-content/65">สินค้าหนึ่งชิ้น ฟุตเทจของคุณ และเรื่องที่อยากเล่า</p></div><button className="btn btn-ghost btn-square btn-sm" aria-label="ปิดสร้างโปรเจกต์" disabled={!!busy} onClick={()=>newDialog.current?.close()}><X className="size-4"/></button></div><form className="space-y-5" onSubmit={e=>{e.preventDefault();if(dirty&&!window.confirm("มีข้อมูลโปรเจกต์เดิมที่ยังไม่บันทึก สร้างใหม่และออกจากโปรเจกต์เดิม?"))return;void perform("create",async()=>{const d=await api<{project:Project}>("/api/projects",{method:"POST",body:body({name:newName,link:newLink,...imported})});acceptProject(d.project);setJobs([]);setEvents([]);setStep("product");setHelp(false);setMobileProjects(false);localStorage.setItem("studio.project",d.project.id);newDialog.current?.close();});}}>
      <InlineErrors/><Field label="วางลิงก์หรือข้อความแชร์จาก Shopee" hint="ถ้าดึงข้อมูลไม่ได้ สามารถกรอกชื่อและรายละเอียดเองได้"><textarea className="textarea min-h-20 w-full" aria-label="ข้อความแชร์จาก Shopee" placeholder="https://shopee.co.th/... หรือ https://shp.ee/..." value={linkInput} onChange={e=>setLinkInput(e.target.value)}/></Field><button type="button" className="btn btn-outline btn-sm" disabled={!linkInput.trim()||!!busy} onClick={()=>void perform("import",async()=>{const d=await api<{name:string;link:string;price:string;facts:string;warnings:string[];imageUrl:string|null}>("/api/import",{method:"POST",body:body({input:linkInput})});setNewName(d.name);setNewLink(d.link);setImported({price:d.price,facts:d.facts});setNotice(d.warnings.join(" · ")||"ดึงข้อมูลสินค้าแล้ว กรุณาตรวจรายละเอียดอีกครั้ง");})}>{busy==="import"?<Spinner/>:<Link2 className="size-4"/>}อ่านข้อมูลจากลิงก์</button>
      <div className="divider text-xs text-base-content/45">รายละเอียดโปรเจกต์</div><Field label="ชื่อสินค้า"><input className="input w-full" required maxLength={240} autoComplete="off" aria-label="ชื่อสินค้าใหม่" placeholder="เช่น กาต้มน้ำที่ใช้ทุกเช้า" value={newName} onChange={e=>setNewName(e.target.value)}/></Field><Field label="ลิงก์ Affiliate เดิม"><input className="input w-full" aria-label="ลิงก์สินค้าใหม่" placeholder="เว้นว่างแล้วเพิ่มภายหลังได้" value={newLink} onChange={e=>setNewLink(e.target.value)}/></Field><div className="modal-action"><button type="button" className="btn btn-ghost" disabled={!!busy} onClick={()=>newDialog.current?.close()}>ยกเลิก</button><button className="btn btn-primary" type="submit" disabled={!newName.trim()||!!busy}>{busy==="create"?<Spinner/>:<Plus className="size-4"/>}สร้างโปรเจกต์</button></div>
    </form></div><form method="dialog" className="modal-backdrop"><button disabled={!!busy}>ปิด</button></form></dialog>
    <dialog ref={archiveDialog} className="modal"><div className="modal-box rounded-2xl"><h2 className="text-xl font-semibold">{project?.archived?"กู้คืนโปรเจกต์นี้?":"เก็บโปรเจกต์เข้าคลัง?"}</h2><p className="mt-3 text-sm leading-relaxed text-base-content/70">ข้อมูลสินค้า สคริปต์ และไฟล์ต้นฉบับยังอยู่ครบ {project?.archived?"โปรเจกต์จะกลับมาในรายการปัจจุบัน":"สามารถกู้คืนจากคลังโปรเจกต์ได้"}</p><div className="modal-action"><button className="btn btn-ghost" disabled={!!busy} onClick={()=>archiveDialog.current?.close()}>ยกเลิก</button><button className="btn btn-primary" disabled={!!busy} onClick={()=>void perform("archive",async()=>{if(!project)return;const p=dirty?await save():project;if(!p)return;const d=await api<{project:Project}>(`/api/projects/${p.id}`,{method:"PATCH",body:body({revision:p.revision,patch:{archived:!p.archived}})});acceptProject(d.project);setShowArchived(d.project.archived);archiveDialog.current?.close();})}><Archive className="size-4"/>{project?.archived?"กู้คืน":"เก็บเข้าคลัง"}</button></div></div></dialog>
    {notice&&<div className="toast toast-center toast-bottom z-50 max-w-[calc(100vw-2rem)]"><div className="alert border border-base-300 bg-base-100 py-3 text-sm shadow-sm" role="status"><CheckCircle2 className="size-4 shrink-0 text-primary"/><span className="leading-relaxed">{notice}</span><button className="btn btn-ghost btn-square btn-xs" aria-label="ปิดการแจ้งเตือน" onClick={()=>setNotice("")}><X className="size-4"/></button></div></div>}
  </div>;
}

function ConnectionGuide({health,busy,refresh,close}:{health:Health|null;busy:boolean;refresh:()=>void;close:()=>void}){
  return <div className="mx-auto max-w-3xl space-y-8"><button className="btn btn-ghost btn-sm px-0" onClick={close}><ArrowLeft className="size-4"/>กลับสตูดิโอ</button><div><h1 className="text-2xl font-semibold">เชื่อมเครื่องมือของคุณ</h1><p className="mt-3 text-sm leading-loose text-base-content/70">ข้อมูลและไฟล์ต้นฉบับเก็บบนเครื่อง ส่วนการสร้างเสียง สคริปต์ AI และตัดต่อจะใช้บริการที่เชื่อมไว้ ระบบนี้เป็นรุ่นใช้ส่วนตัวก่อนเปิดขาย</p></div><div className="divide-y divide-base-300/60 rounded-2xl border border-base-300/60 bg-base-100 px-5">{[{label:"Codex CLI",ok:health?.capcut.cli,detail:health?.capcut.cli?"พบตัวเชื่อมบนเครื่อง":"ตั้ง CODEX_CLI เป็น path ของ codex"},{label:"CapCut × Codex",ok:health?.capcut.installed,detail:health?.capcut.message||"กำลังตรวจ"},{label:"Edge TTS (เสียงทางเลือก)",ok:health?.voice,detail:health?.voice?"พร้อมเรียก edge-tts":"ติดตั้ง requirements.txt และตั้ง PYTHON_PATH"},{label:"Gemini — สคริปต์และเสียง 3.8 Flash TTS",ok:health?.ai,detail:health?.ai?"ตั้งคีย์แล้ว ใช้โหลดเสียงโคลนเดิมได้ · ยังไม่ได้ตรวจโควตา":"ใช้โครงสคริปต์ได้ทันที หรือเพิ่ม GEMINI_API_KEY"}].map(x=><div key={x.label} className="flex items-center gap-4 py-5">{x.ok?<CheckCircle2 className="size-5 shrink-0 text-success"/>:<Circle className="size-5 shrink-0 text-base-content/40"/>}<div><h2 className="text-sm font-medium">{x.label}</h2><p className="mt-1 text-xs leading-relaxed text-base-content/65">{x.detail}</p></div></div>)}</div><button className="btn btn-outline btn-sm" disabled={busy} onClick={refresh}><RefreshCw className="size-4"/>ตรวจสถานะอีกครั้ง</button><section className="space-y-3"><h2 className="text-lg font-semibold">เริ่มใช้ CapCut</h2><ol className="list-decimal space-y-3 pl-5 text-sm leading-loose text-base-content/75"><li>เปิดหน้า CapCut × Codex ทางการ และทำตามขั้นตอนติดตั้งปลั๊กอินใน Codex</li><li>อนุญาตบัญชี CapCut ในเบราว์เซอร์ของ Codex ด้วยตัวคุณเอง</li><li>ในสตูดิโอ ตรวจความพร้อมแล้วเลือก “เตรียมงานให้ Codex”</li><li>คัดลอกคำสั่งไปแชต Codex เพื่อส่งฟุตเทจจริงไปตัดต่อ แล้วเปิด draft ตรวจงาน</li></ol><a className="btn btn-outline btn-sm mt-3" href="https://www.capcut.com/tools/capcut-x-codex" target="_blank" rel="noopener noreferrer">คู่มือ CapCut × Codex ทางการ<ExternalLink className="size-4"/></a></section><section className="space-y-3"><h2 className="text-lg font-semibold">เพิ่มเครื่องมือสตูดิโอให้ Codex</h2><p className="text-sm leading-loose text-base-content/70">โปรเจกต์นี้มี MCP server สำหรับค้นโปรเจกต์ อ่านฟุตเทจและ brief และบันทึกผล CapCut กลับโดยตรง ดูคำสั่งติดตั้งที่ README.md ในโฟลเดอร์ shopee_gpt</p></section><div className="alert alert-info alert-soft text-sm leading-relaxed">การพบปลั๊กอินไม่ใช่การยืนยันว่าสิทธิ์บัญชีพร้อม งานที่ต้องตอบฟอร์มหรืออนุญาตเพิ่มเติมให้ทำต่อในแชต Codex ระบบจะไม่ซื้อเครดิตหรือโพสต์วิดีโอให้เอง</div></div>;
}
